#include <iostream>
using namespace std;

int main() {
    int balance = 100;
    balance += 50;
    balance -= 30;
    balance *= 2;
    balance /= 5;
    balance %= 10;
    cout << "balance = " << balance << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int r1 = 10 + 6 / 2 * 3 - 4 % 3;
    int r2 = (10 + 6) / 2 * 3 - 4 % 3;
    int r3 = 100 / 10 / 2;
    int a, b, c;
    a = b = c = 4;
    cout << r1 << " " << r2 << " " << r3 << endl;
    cout << a << " " << b << " " << c << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int x = 10, y = 3;
    x += y * 2;
    y -= 1;
    x %= y + 3;
    cout << x << " " << y << endl;
    return 0;
}

